public async Task<User?> GetUserAsync(string id, CancellationToken ct)
{
    if (string.IsNullOrWhiteSpace(id))
        throw new ArgumentException("Id required", nameof(id));

    var cached = await _cache.GetAsync<User>(CacheKey(id), ct);
    if (cached is not null)
        return cached;

    return await _db.Users.FindAsync(id, ct);
}

public IActionResult MapError(Exception ex) => ex switch
{
    NotFoundException n => NotFound(n.Message),
    ValidationException v => BadRequest(v.Errors),
    OperationCanceledException => StatusCode(499),
    _ => Problem("Unexpected error")
};

public sealed class OrderService(IOrderRepository repo, ICache cache)
{
    public async Task SubmitAsync(OrderDto order, CancellationToken ct) =>
        await repo.SaveAsync(order, ct);
}
